1	import { useState, useEffect, useCallback, useId } from "react";
2	import { useNavigate, useSearchParams } from "react-router-dom";
3	import {
4	  ScanLine,
5	  Info,
6	  AlertCircle,
7	  Loader2,
8	  Globe,
9	} from "lucide-react";
10	import { Card, CardContent } from "@/components/ui/card";
11	import { Button } from "@/components/ui/button";
12	import { Input } from "@/components/ui/input";
13	import { Progress } from "@/components/ui/progress";
14	import {
15	  Select,
16	  SelectContent,
17	  SelectItem,
18	  SelectTrigger,
19	  SelectValue,
20	} from "@/components/ui/select";
21	import { ScanProgressTimeline } from "@/components/shared/ScanProgressTimeline";
22	import { BrowserFrame } from "@/components/shared/BrowserFrame";
23	import { PageTransition } from "@/components/shared/PageTransition";
24	import { ScanGateWall } from "@/components/shared/ScanGateWall";
25	import { CRO_PILLARS, SCAN_STEPS, PAGE_TYPES } from "@/lib/constants";
26	import { useAuth } from "@/contexts/AuthContext";
27	import { useCreateScan } from "@/hooks/use-scans";
28	import { useScan } from "@/hooks/use-scans";
29	import { useFeatureFlag } from "@/hooks/use-feature-flag";
30	import { toast } from "sonner";
31	import type { PageType } from "@/types";
32	import { cn } from "@/lib/utils";
33	
34	/** Generate a stable teaser score 45–72 for an unauthenticated guest scan */
35	function generateTeaserScore(url: string): number {
36	  let hash = 0;
37	  for (let i = 0; i < url.length; i++) {
38	    hash = (hash * 31 + url.charCodeAt(i)) & 0xffffffff;
39	  }
40	  return 45 + (Math.abs(hash) % 28);
41	}
42	
43	/** Basic URL validation — checks structure, not reachability */
44	function isValidUrl(str: string): boolean {
45	  try {
46	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
47	    return url.protocol === "https:" || url.protocol === "http:";
48	  } catch {
49	    return false;
50	  }
51	}
52	
53	/** Normalize URL: prepend https:// if missing */
54	function normalizeUrl(str: string): string {
55	  const trimmed = str.trim();
56	  if (!trimmed) return trimmed;
57	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
58	  return `https://${trimmed}`;
59	}
60	
61	// ── Map scan status to step index ───────────────────────────────
62	
63	function statusToStep(status: string): number {
64	  switch (status) {
65	    case "pending": return 0;
66	    case "analyzing": return 3;
67	    case "completed": return SCAN_STEPS.length;
68	    case "failed": return -1;
69	    default: return 0;
70	  }
71	}
72	
73	const Scan = () => {
74	  const navigate = useNavigate();
75	  const [searchParams] = useSearchParams();
76	  const [rawUrl, setRawUrl] = useState(searchParams.get("url") || "");
77	  const [pageType, setPageType] = useState<PageType>(
78	    (searchParams.get("type") as PageType) || "landing"
79	  );
80	  const [urlError, setUrlError] = useState<string | null>(null);
81	
82	  // activeScanId drives the polling query (authenticated users only)
83	  const [activeScanId, setActiveScanId] = useState<string | null>(null);
84	  const [simulatedStep, setSimulatedStep] = useState(-1);
85	  const [scanFailed, setScanFailed] = useState(false);
86	
87	  // Guest flow: simulate the animation then show gate wall
88	  const [guestAnimating, setGuestAnimating] = useState(false);
89	  const [guestAnimationDone, setGuestAnimationDone] = useState(false);
90	  const [guestTeaserScore, setGuestTeaserScore] = useState(0);
91	
92	  const inputId = useId();
93	  const { user, profile } = useAuth();
94	  const isAuthenticated = !!user;
95	  const freeScanEnabled = useFeatureFlag("free_scan_enabled", true);
96	  const createScan = useCreateScan();
97	
98	  const scansUsed = profile?.scans_used ?? 0;
99	  const scanLimit = profile?.scan_limit ?? 3;
100	  const scansRemaining = scanLimit - scansUsed;
101	  const atLimit = scansRemaining <= 0;
102	
103	  // Poll the scan row while it's pending/analyzing
104	  const { data: pollingScan } = useScan(activeScanId ?? undefined, {
105	    refetchInterval: activeScanId ? 2000 : false,
106	  });
107	
108	  const isAnalyzing = activeScanId !== null || guestAnimating;
109	  const normalizedUrl = normalizeUrl(rawUrl);
110	
111	  const totalSteps = SCAN_STEPS.length;
112	  const currentStep = isAnalyzing
113	    ? pollingScan
114	      ? statusToStep(pollingScan.status)
115	      : simulatedStep
116	    : -1;
117	  const progressPercent = currentStep < 0 ? 0 : Math.round(((currentStep + 1) / totalSteps) * 100);
118	
119	  // When polling finds a completed/failed scan, navigate or show error
120	  useEffect(() => {
121	    if (!pollingScan) return;
122	    if (pollingScan.status === "completed") {
123	      setTimeout(() => navigate(`/reports/${pollingScan.id}`), 600);
124	    } else if (pollingScan.status === "failed") {
125	      setActiveScanId(null);
126	      setSimulatedStep(-1);
127	      setScanFailed(true);
128	    }
129	    // eslint-disable-next-line react-hooks/exhaustive-deps
130	  }, [pollingScan?.status]);
131	
132	  // Simulate step progression while waiting for the edge function (authenticated)
133	  useEffect(() => {
134	    if (!isAnalyzing || !activeScanId) return;
135	    if (pollingScan?.status === "completed" || pollingScan?.status === "failed") return;
136	    if (simulatedStep >= totalSteps - 1) return;
137	
138	    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
139	    const timer = setTimeout(
140	      () => setSimulatedStep((prev) => prev + 1),
141	      durations[simulatedStep] ?? 1200
142	    );
143	    return () => clearTimeout(timer);
144	    // totalSteps is derived from a constant — safe to omit
145	    // eslint-disable-next-line react-hooks/exhaustive-deps
146	  }, [isAnalyzing, activeScanId, simulatedStep, pollingScan?.status]);
147	
148	  // Guest simulated step progression — no API call, just animation
149	  useEffect(() => {
150	    if (!guestAnimating || guestAnimationDone) return;
151	    if (simulatedStep >= totalSteps - 1) {
152	      // Animation finished — show gate wall
153	      const timer = setTimeout(() => {
154	        setGuestAnimationDone(true);
155	        setGuestAnimating(false);
156	      }, 800);
157	      return () => clearTimeout(timer);
158	    }
159	
160	    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
161	    const timer = setTimeout(
162	      () => setSimulatedStep((prev) => prev + 1),
163	      durations[simulatedStep] ?? 1200
164	    );
165	    return () => clearTimeout(timer);
166	    // eslint-disable-next-line react-hooks/exhaustive-deps
167	  }, [guestAnimating, guestAnimationDone, simulatedStep]);
168	
169	  const startAnalysis = useCallback(() => {
170	    setUrlError(null);
171	    if (!rawUrl.trim()) {
172	      setUrlError("Please enter a URL.");
173	      return;
174	    }
175	    if (!isValidUrl(normalizedUrl)) {
176	      setUrlError("Enter a valid URL like https://example.com/page");
177	      return;
178	    }
179	
180	    // Unauthenticated users: if free scan disabled, redirect to signup immediately
181	    if (!isAuthenticated) {
182	      if (!freeScanEnabled) {
183	        navigate("/signup");
184	        return;
185	      }
186	      setGuestAnimating(true);
187	      setGuestAnimationDone(false);
188	      setGuestTeaserScore(generateTeaserScore(normalizedUrl));
189	      setSimulatedStep(0);
190	      return;
191	    }
192	
193	    if (atLimit) return;
194	
195	    setSimulatedStep(0);
196	
197	    createScan.mutate(
198	      { url: normalizedUrl, page_type: pageType },
199	      {
200	        onSuccess: (scan) => {
201	          setActiveScanId(scan.id);
202	        },
203	        onError: (err: unknown) => {
204	          setSimulatedStep(-1);
205	          const message = err instanceof Error ? err.message : "Failed to start scan";
206	          toast.error(message);
207	        },
208	      }
209	    );
210	  }, [rawUrl, normalizedUrl, pageType, isAuthenticated, atLimit, createScan]);
211	
212	  const handleSubmit = (e: React.FormEvent) => {
213	    e.preventDefault();
214	    startAnalysis();
215	  };
216	
217	  // ── Guest Gate Wall ─────────────────────────────────────────
218	  if (guestAnimationDone) {
219	    return (
220	      <PageTransition>
221	        <ScanGateWall teaserScore={guestTeaserScore} url={normalizedUrl} />
222	      </PageTransition>
223	    );
224	  }
225	
226	  // ── Analysis Progress View ──────────────────────────────────
227	  if (isAnalyzing) {
228	    let hostname = rawUrl;
229	    try { hostname = new URL(normalizedUrl).hostname; } catch { /* keep raw */ }
230	
231	    const displayStep = Math.max(0, currentStep);
232	
233	    return (
234	      <PageTransition>
235	        <div className="mx-auto max-w-2xl space-y-6">
236	          <div>
237	            <h2 className="text-xl font-semibold tracking-tight text-foreground">Analyzing your page</h2>
238	            <p className="mt-1 text-sm text-muted-foreground">
239	              Scanning <span className="font-medium text-foreground">{hostname}</span> — this usually takes 20-40 seconds
240	            </p>
241	          </div>
242	
243	          {/* Progress bar */}
244	          <div className="space-y-1.5">
245	            <div className="flex items-center justify-between text-sm">
246	              <span className="text-muted-foreground">
247	                Step {Math.min(displayStep + 1, totalSteps)} of {totalSteps}
248	              </span>
249	              <span className="tabular-nums font-medium text-foreground">{Math.min(progressPercent, 100)}%</span>
250	            </div>
251	            <Progress value={Math.min(progressPercent, 100)} className="h-2" />
252	          </div>
253	
254	          {/* Browser frame */}
255	          <BrowserFrame url={normalizedUrl}>
256	            <div className="relative flex h-52 items-center justify-center bg-gradient-to-br from-slate-50 via-white to-slate-50">
257	              {/* Scanning animation */}
258	              <div className="absolute inset-x-0 top-0 h-1 overflow-hidden">
259	                <div className="h-full w-1/3 animate-[shimmer_1.5s_ease-in-out_infinite] bg-gradient-to-r from-transparent via-primary/30 to-transparent" />
260	              </div>
261	              <div className="text-center">
262	                <Loader2 className="mx-auto mb-3 h-8 w-8 animate-spin text-primary" />
263	                <p className="text-sm font-medium text-muted-foreground">
264	                  {displayStep < totalSteps ? SCAN_STEPS[displayStep]?.label : "Finalizing report"}...
265	                </p>
266	              </div>
267	            </div>
268	          </BrowserFrame>
269	
270	          {/* Timeline */}
271	          <Card className="border-border/50 shadow-soft">
272	            <CardContent className="p-6">
273	              <ScanProgressTimeline steps={SCAN_STEPS} currentStep={displayStep} />
274	            </CardContent>
275	          </Card>
276	        </div>
277	      </PageTransition>
278	    );
279	  }
280	
281	  // ── URL Input Form ──────────────────────────────────────────
282	  return (
283	    <PageTransition>
284	      <div className="mx-auto max-w-2xl space-y-8">
285	        <div className="text-center">
286	          <h2 className="text-xl font-semibold tracking-tight text-foreground">Analyze your page</h2>
287	          <p className="mt-2 text-muted-foreground">
288	            Enter any URL to get a detailed CRO audit with actionable recommendations
289	          </p>
290	        </div>
291	
292	        {/* URL Input Card */}
293	        <Card className="border-border/50 shadow-soft">
294	          <CardContent className="p-8">
295	            <form onSubmit={handleSubmit} className="space-y-4">
296	              <div>
297	                <label htmlFor={inputId} className="mb-1.5 block text-sm font-medium text-foreground">
298	                  Page URL
299	                </label>
300	                <div className="relative">
301	                  <Globe className="absolute left-4 top-1/2 h-4.5 w-4.5 -translate-y-1/2 text-muted-foreground" />
302	                  <Input
303	                    id={inputId}
304	                    type="text"
305	                    placeholder="example.com/landing-page"
306	                    value={rawUrl}
307	                    onChange={(e) => { setRawUrl(e.target.value); setUrlError(null); }}
308	                    className={cn(
309	                      "h-14 rounded-xl border-border/50 bg-card pl-11 pr-5 text-base placeholder:text-muted-foreground focus-visible:border-primary focus-visible:ring-primary/20",
310	                      urlError && "border-red-300 focus-visible:border-red-400 focus-visible:ring-red-400/20"
311	                    )}
312	                  />
313	                </div>
314	                {urlError && (
315	                  <p className="mt-1.5 flex items-center gap-1 text-sm text-red-600">
316	                    <AlertCircle className="h-3.5 w-3.5" />
317	                    {urlError}
318	                  </p>
319	                )}
320	              </div>
321	
322	              <div>
323	                <label className="mb-1.5 block text-sm font-medium text-foreground">Page type</label>
324	                <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
325	                  <SelectTrigger className="h-12 rounded-xl border-border/50 bg-card">
326	                    <SelectValue placeholder="Select page type" />
327	                  </SelectTrigger>
328	                  <SelectContent>
329	                    {PAGE_TYPES.map((type) => (
330	                      <SelectItem key={type.value} value={type.value}>
331	                        {type.label}
332	                      </SelectItem>
333	                    ))}
334	                  </SelectContent>
335	                </Select>
336	                <p className="mt-1 text-xs text-muted-foreground">
337	                  Page type affects how we weight each CRO pillar in the overall score
338	                </p>
339	              </div>
340	
341	              <Button
342	                type="submit"
343	                className="h-14 w-full rounded-xl text-base font-semibold"
344	                disabled={!rawUrl.trim() || (isAuthenticated && (atLimit || createScan.isPending)) || guestAnimating}
345	              >
346	                {isAuthenticated && atLimit ? (
347	                  "Scan limit reached — Upgrade to continue"
348	                ) : isAuthenticated && createScan.isPending ? (
349	                  <>
350	                    <Loader2 className="mr-2 h-5 w-5 animate-spin" />
351	                    Starting scan...
352	                  </>
353	                ) : !isAuthenticated ? (
354	                  <>
355	                    <ScanLine className="mr-2 h-5 w-5" />
356	                    Analyze Free — No Sign Up Needed
357	                  </>
358	                ) : (
359	                  <>
360	                    <ScanLine className="mr-2 h-5 w-5" />
361	                    Start Analysis
362	                  </>
363	                )}
364	              </Button>
365	            </form>
366	
367	            {/* Usage indicator — only shown to authenticated users */}
368	            {isAuthenticated ? (
369	              <div className="mt-4 flex items-center justify-center gap-4 text-xs text-muted-foreground">
370	                <span className="flex items-center gap-1">
371	                  {atLimit ? (
372	                    <AlertCircle className="h-3.5 w-3.5 text-red-500" />
373	                  ) : scansRemaining === 1 ? (
374	                    <AlertCircle className="h-3.5 w-3.5 text-amber-500" />
375	                  ) : (
376	                    <Info className="h-3.5 w-3.5" />
377	                  )}
378	                  {scansUsed}/{scanLimit} scans used this month
379	                </span>
380	                <span>&middot;</span>
381	                <span>~30 seconds per scan</span>
382	              </div>
383	            ) : (
384	              <div className="mt-4 rounded-lg border border-blue-100 bg-blue-50/60 px-4 py-3 text-center">
385	                <p className="text-xs text-blue-700">
386	                  Free account — 3 scans/month, no credit card required.{" "}
387	                  <a href="/signup" className="font-medium underline underline-offset-2 hover:text-blue-900">
388	                    Create account
389	                  </a>
390	                </p>
391	              </div>
392	            )}
393	          </CardContent>
394	        </Card>
395	
396	        {/* Scan failure retry card */}
397	        {scanFailed && (
398	          <Card className="border-destructive/30 bg-destructive/5">
399	            <CardContent className="flex items-center gap-4 p-6">
400	              <AlertCircle className="h-8 w-8 text-destructive shrink-0" />
401	              <div>
402	                <p className="font-medium text-foreground">Analysis failed</p>
403	                <p className="text-sm text-muted-foreground mt-0.5">
404	                  The scan engine encountered an error. Your scan count was not affected.
405	                </p>
406	              </div>
407	              <Button
408	                onClick={() => { setScanFailed(false); startAnalysis(); }}
409	                className="ml-auto shrink-0"
410	              >
411	                Try Again
412	              </Button>
413	            </CardContent>
414	          </Card>
415	        )}
416	
417	        {/* What we analyze */}
418	        <div>
419	          <h3 className="mb-4 text-center text-xs font-semibold uppercase tracking-widest text-muted-foreground">
420	            7 pillars we analyze
421	          </h3>
422	          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
423	            {CRO_PILLARS.map((pillar) => {
424	              const Icon = pillar.icon;
425	              return (
426	                <Card
427	                  key={pillar.key}
428	                  className="group border-border/50 shadow-soft hover:shadow-soft-md transition-all"
429	                >
430	                  <CardContent className="flex flex-col items-center p-4 text-center">
431	                    <div className="mb-2.5 flex h-9 w-9 items-center justify-center rounded-lg bg-primary/8 group-hover:bg-primary/15 transition-colors">
432	                      <Icon className="h-4 w-4 text-primary" />
433	                    </div>
434	                    <p className="text-xs font-medium text-foreground leading-tight">
435	                      {pillar.label}
436	                    </p>
437	                    <p className="mt-1 text-2xs leading-snug text-muted-foreground">
438	                      {Math.round(pillar.weight * 100)}% weight
439	                    </p>
440	                  </CardContent>
441	                </Card>
442	              );
443	            })}
444	          </div>
445	        </div>
446	
447	        {/* How scoring works */}
448	        <Card className="border-border/40 bg-muted/30 shadow-none">
449	          <CardContent className="p-5">
450	            <div className="flex items-start gap-3">
451	              <Info className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
452	              <div className="text-xs text-muted-foreground leading-relaxed">
453	                <span className="font-medium text-foreground">How scoring works:</span> Each pillar is scored 0-100 based on specific checks.
454	                Pillar weights vary by page type — for example, CTA Effectiveness is weighted 22% on landing pages but only 12% on blog posts.
455	                Your overall score is a weighted average compared against industry benchmarks.
456	              </div>
457	            </div>
458	          </CardContent>
459	        </Card>
460	      </div>
461	    </PageTransition>
462	  );
463	};
464	
465	export default Scan;
