1	import React, { useEffect, useState } from "react";
2	import { getScoreHex, getScoreLabel } from "@/lib/score-utils";
3	import { cn } from "@/lib/utils";
4	
5	interface ScoreRingProps {
6	  score: number;
7	  size?: number;
8	  strokeWidth?: number;
9	  showLabel?: boolean;
10	  className?: string;
11	}
12	
13	export const ScoreRing = React.forwardRef<HTMLDivElement, ScoreRingProps>(function ScoreRing({
14	  score,
15	  size = 120,
16	  strokeWidth = 8,
17	  showLabel = true,
18	  className,
19	}, ref) {
20	  const [animatedOffset, setAnimatedOffset] = useState(0);
21	  const radius = (size - strokeWidth) / 2;
22	  const circumference = 2 * Math.PI * radius;
23	  const targetOffset = circumference * (1 - score / 100);
24	
25	  useEffect(() => {
26	    setAnimatedOffset(circumference);
27	    const timer = setTimeout(() => setAnimatedOffset(targetOffset), 50);
28	    return () => clearTimeout(timer);
29	  }, [score, circumference, targetOffset]);
30	
31	  const color = getScoreHex(score);
32	  const label = getScoreLabel(score);
33	  const center = size / 2;
34	  const fontSize = size * 0.28;
35	  const labelSize = size * 0.09;
36	
37	  // Glow shadow based on score color
38	  const glowShadow = score >= 70
39	    ? "drop-shadow(0 0 6px rgba(34, 197, 94, 0.2))"
40	    : score >= 40
41	    ? "drop-shadow(0 0 6px rgba(245, 158, 11, 0.2))"
42	    : "drop-shadow(0 0 6px rgba(239, 68, 68, 0.2))";
43	
44	  return (
45	    <div
46	      ref={ref}
47	      role="img"
48	      aria-label={`CRO Score: ${score} out of 100`}
49	      className={cn("relative inline-flex flex-col items-center", className)}
50	    >
51	      <svg
52	        width={size}
53	        height={size}
54	        className="transform -rotate-90"
55	        style={{ filter: glowShadow }}
56	      >
57	        {/* Background circle */}
58	        <circle
59	          cx={center}
60	          cy={center}
61	          r={radius}
62	          fill="none"
63	          stroke="currentColor"
64	          strokeWidth={strokeWidth}
65	          className="text-muted/60"
66	        />
67	        {/* Score circle */}
68	        <circle
69	          cx={center}
70	          cy={center}
71	          r={radius}
72	          fill="none"
73	          stroke={color}
74	          strokeWidth={strokeWidth}
75	          strokeLinecap="round"
76	          strokeDasharray={circumference}
77	          strokeDashoffset={animatedOffset}
78	          style={{ transition: "stroke-dashoffset 1s ease-out" }}
79	        />
80	      </svg>
81	      {/* Score number centered */}
82	      <div className="absolute inset-0 flex flex-col items-center justify-center">
83	        <span
84	          className="font-semibold text-foreground tabular-nums"
85	          style={{ fontSize: `${fontSize}px`, lineHeight: 1 }}
86	        >
87	          {score}
88	        </span>
89	        <span
90	          className="text-muted-foreground"
91	          style={{ fontSize: `${labelSize}px` }}
92	        >
93	          /100
94	        </span>
95	      </div>
96	      {showLabel && (
97	        <span
98	          className="mt-1 text-xs font-medium"
99	          style={{ color }}
100	        >
101	          {label}
102	        </span>
103	      )}
104	    </div>
105	  );
