32	          : "bg-card text-muted-foreground border-border/50 hover:bg-muted/40 hover:text-foreground"
33	      )}
34	    >
35	      {copied ? <><Check className="h-2.5 w-2.5" />Copied</> : <><Copy className="h-2.5 w-2.5" />Copy</>}
